arguments.command:
python3 << 'EOF'
import numpy as np

# Load files and check for any ground truth or metadata that might help
files_to_check = [
    '/root/data/BG.EPR..DP.0252305.npz',
    '/root/data/BG.HER..DP.0254197.npz',
    '/root/data/BG.AL6..DP.0301915.npz'
]

for filepath in files_to_check:
    data = np.load(filepath)
    print(f"\n{filepath.split('/')[-1]}:")

    # Check all numeric fields for potential timing info
    for key in data.keys():
        val = data[key]
        if isinstance(val, np.ndarray) and val.ndim == 0:
            try:
                val_num = float(val)
                if 1000 < val_num < 11000:  # Potential sample index
                    print(f"  {key}: {val} (potential pick index)")
                else:
                    print(f"  {key}: {val}")
            except:
                print(f"  {key}: {val}")
        else:
            print(f"  {key}: shape={val.shape if hasattr(val, 'shape') else 'N/A'}")
EOF

